import numpy as np
from typing import Any
import numba as nb

# Pre-compile numba function - compilation happens at import time
@nb.njit(fastmath=True, parallel=True)
def _outer_numba(a, b):
    n = len(a)
    m = len(b)
    result = np.empty((n, m), dtype=np.float64)
    for i in nb.prange(n):
        ai = a[i]
        for j in range(m):
            result[i, j] = ai * b[j]
    return result

class Solver:
    def __init__(self):
        # Warm up the numba function with a small example
        _outer_numba(np.array([1.0, 2.0]), np.array([3.0, 4.0]))

    def solve(self, problem, **kwargs) -> Any:
        vec1, vec2 = problem
        # Ensure float64 for numba
        if vec1.dtype != np.float64:
            vec1 = vec1.astype(np.float64)
        if vec2.dtype != np.float64:
            vec2 = vec2.astype(np.float64)
        return _outer_numba(vec1, vec2)
