import numpy as np
from typing import Any

class Solver:
    def solve(self, problem, **kwargs) -> Any:
        vec1, vec2 = problem
        n = len(vec1)
        # Use einsum for smaller vectors (faster due to less overhead)
        # Use multiply with out parameter for larger vectors (better memory access pattern)
        if n < 2000:
            return np.einsum('i,j->ij', vec1, vec2)
        else:
            result = np.empty((n, n))
            np.multiply(vec1[:, np.newaxis], vec2[np.newaxis, :], out=result)
            return result
